-- ══════════════════════════════════════════════════════════════════
-- استيراد بيان تراخيص جمع المال 2025 (بيان التصفية - 437 صف)
-- شغّلي هذا الملف بعد 00_wipe_all_organizations_data.sql و 01_import_central_orgs_FIXED.sql
--
-- اللي بيعمله السكريبت ده بالترتيب:
--   1) بيحمّل الـ 437 صف من البيان في جدول مؤقت (staging).
--   2) بيضيف الجمعيات اللي مش موجودة أصلاً في Organizations:
--        - 296 جمعية "مديرية" (لسه معندناش بيان المديريات الرسمي)
--        - 5 جمعيات "مركزي" رقم قيدها مش موجود في ملف الاستيراد الحالي
--      كل الجمعيات دي بتتضاف بحالة N'تحتاج مراجعة' (نفس القيمة اللي
--      السيرفر والواجهة بيتعاملوا معاها فعليًا كـ"تحت المراجعة" وبتختفي
--      بصمت من كل إحصاء/تقرير جمع المال - server_v15.js سطر 7226)
--      + ملحوظة في عمود Notes توضح إنها اتضافت تلقائيًا من البيان ده
--      ومحتاجة استكمال بيانات (رئيس مجلس الإدارة، الهاتف..) عند توفرها.
--   3) بعد كده بيضيف صفوف FundraisingLicenses وبيربطها بالجمعية الصح
--      (مطابقة بنفس منطق checkRegNumDuplicate في السيرفر: مركزي = رقم
--      القيد بس، مديرية = رقم القيد + المحافظة).
--
-- الحقول اللي اتحطت باجتهاد ومحتاجة تراجعيها:
--   • LicenseStatus = N'متصفي' لكل الصفوف (لأن كل صف في البيان ده معاه
--     شهر/سنة تصفية فعلي بالفعل - مش تراخيص لسه سارية)
--   • DataType = N'قديمة' (لأن عندنا شهر/سنة تصفية بس من غير تاريخ تصفية
--     دقيق - ده بالظبط تعريف "قديمة" في تعليق السيرفر سطر 29-33)
--   • LiquidationStatus اتحسبت من عمود "مدة التصفية" في البيان:
--     0 أو فاضي = "داخل مهلة التصفية"، غير كده = "بعد المهلة بـ N يوم"
--   • IssueYear = سنة "المدة من" (بداية فترة الترخيص) = 2025 في كل الصفوف
--     تقريبًا (مفيش تاريخ إصدار صريح في البيان)
--   • OrgType للجمعيات المديرية الجديدة = N'جمعية' (مش موجود في البيان
--     أصلاً لأي صف مديرية - القيمة الافتراضية في السكيما نفسها)
--
-- التكرار: السكريبت ده Idempotent - تقدري تشغّليه أكتر من مرة من غير ما
-- يكرر ولا جمعية ولا ترخيص (بيستخدم نفس شرط UQ_License الفعلي في القاعدة:
-- OrgID + LicenseNumber + IssueYear، وبيتأكد الجمعية مش موجودة قبل ما يضيفها).
-- ══════════════════════════════════════════════════════════════════

USE NGO_System;
GO

IF OBJECT_ID('tempdb..#Stage2025') IS NOT NULL DROP TABLE #Stage2025;

CREATE TABLE #Stage2025 (
  RowNum INT IDENTITY(1,1) PRIMARY KEY,
  OrgName NVARCHAR(500) COLLATE DATABASE_DEFAULT, OrgType NVARCHAR(50) COLLATE DATABASE_DEFAULT,
  RegNum INT, RegYear INT NULL,
  Address NVARCHAR(1000) COLLATE DATABASE_DEFAULT, Level NVARCHAR(50) COLLATE DATABASE_DEFAULT, Governorate NVARCHAR(100) COLLATE DATABASE_DEFAULT NULL,
  StartDate DATE NULL, EndDate DATE NULL,
  CollectionMethods NVARCHAR(500) COLLATE DATABASE_DEFAULT,
  Revenue DECIMAL(18,2), Expenses DECIMAL(18,2),
  LiqMonth INT NULL, LiqYear INT NULL, LiqStatus NVARCHAR(150) COLLATE DATABASE_DEFAULT NULL,
  LicenseNumber NVARCHAR(100) COLLATE DATABASE_DEFAULT, IssueYear INT NULL
);
GO

