-- ── 1) إضافة الجمعيات الناقصة (مديرية أو مركزي) بحالة "تحتاج مراجعة" ──
INSERT INTO Organizations
  (OrgName, OrgType, RegNum, RegYear, Address, Level, Governorate, Status, Notes, IsActive)
SELECT DISTINCT
  s.OrgName, s.OrgType, s.RegNum, s.RegYear, s.Address, s.Level, s.Governorate,
  N'تحتاج مراجعة',
  N'أُضيفت تلقائيًا أثناء استيراد بيان تراخيص جمع المال 2025 (مش من بيان قيد رسمي) - يلزم استكمال باقي البيانات الإدارية ومراجعتها',
  1
FROM #Stage2025 s
WHERE NOT EXISTS (
  SELECT 1 FROM Organizations o
  WHERE (s.Level = N'مركزي' AND o.Level = N'مركزي' AND o.RegNum = s.RegNum)
     OR (s.Level = N'مديرية' AND o.Level = N'مديرية' AND o.RegNum = s.RegNum
         AND ISNULL(o.Governorate,N'') = ISNULL(s.Governorate,N''))
);
GO

-- ── 2) إضافة تراخيص جمع المال وربطها بالجمعية الصحيحة ──
INSERT INTO FundraisingLicenses
  (OrgID, LicenseNumber, LicenseStatus, StartDate, EndDate,
   LiquidationMonth, LiquidationYear, Revenue, Expenses, LiquidationStatus,
   DataType, CollectionMethods, IssueYear, Department)
SELECT
  o.OrgID, s.LicenseNumber, N'متصفي', s.StartDate, s.EndDate,
  s.LiqMonth, s.LiqYear, s.Revenue, s.Expenses, s.LiqStatus,
  N'قديمة', s.CollectionMethods, s.IssueYear, N'جمع المال'
FROM #Stage2025 s
JOIN Organizations o
  ON (s.Level = N'مركزي' AND o.Level = N'مركزي' AND o.RegNum = s.RegNum)
  OR (s.Level = N'مديرية' AND o.Level = N'مديرية' AND o.RegNum = s.RegNum
      AND ISNULL(o.Governorate,N'') = ISNULL(s.Governorate,N''))
WHERE NOT EXISTS (
  SELECT 1 FROM FundraisingLicenses fl
  WHERE fl.OrgID = o.OrgID AND fl.LicenseNumber = s.LicenseNumber
    AND ISNULL(fl.IssueYear,-1) = ISNULL(s.IssueYear,-1)
);
GO

-- ── تقرير سريع بعد الاستيراد ──
DECLARE @newOrgs INT = (SELECT COUNT(*) FROM Organizations WHERE Status=N'تحتاج مراجعة');
DECLARE @newLics INT = (SELECT COUNT(*) FROM FundraisingLicenses WHERE DataType=N'قديمة' AND Department=N'جمع المال');
DECLARE @unmatched INT = (
  SELECT COUNT(*) FROM #Stage2025 s
  WHERE NOT EXISTS (
    SELECT 1 FROM Organizations o
    WHERE (s.Level = N'مركزي' AND o.Level = N'مركزي' AND o.RegNum = s.RegNum)
       OR (s.Level = N'مديرية' AND o.Level = N'مديرية' AND o.RegNum = s.RegNum
           AND ISNULL(o.Governorate,N'') = ISNULL(s.Governorate,N''))
  )
);
PRINT N'✅ عدد الجمعيات اللي بقت "تحتاج مراجعة" دلوقتي (تراكمي في القاعدة كلها) = ' + CAST(@newOrgs AS NVARCHAR);
PRINT N'✅ عدد تراخيص جمع المال المستوردة (DataType=قديمة, قسم جمع المال) = ' + CAST(@newLics AS NVARCHAR);
IF @unmatched > 0
  PRINT N'⚠️ تحذير: لسه فيه ' + CAST(@unmatched AS NVARCHAR) + N' صف من البيان معملوش match مع أي جمعية - راجعيهم يدوي.';
ELSE
  PRINT N'✅ كل صفوف البيان (437) اتربطت بجمعية بنجاح.';

DROP TABLE #Stage2025;
GO
